			function doList(psStatus){
			    
			    //조회 서브미션 호출
			    util.Submit.send(app, "subList", function(pbSuccess){
			        if(pbSuccess) {
			            //첨부 파일 조회
			            app.lookup("cmnsinglefileupload").getFiles();
			            
			            if(psStatus == "save"){
			                //갱신된 데이터가 조회되었습니다.
			                util.Msg.notify(app, "INF-M005");
			                setCrud("READ");
			            }else{
			                //조회되었습니다.
			                util.Msg.notify(app, "INF-M001");
			            }

			            util.Control.redraw(app, "grpData");
			         
			            // 위원회구분 itemclick                     
			            util.Control.dispatchEvent(app, "rdbCmitSe", "item-click");
			            
			        }
			    });
			}

