			/**
			 * 팝업 조건에 따라 CRUD 적용
			 * @param String psType
			 */
			function setCrud(psType){
			    
			    if(psType == "CREATE"){
			        app.lookup("dsList").addRowData({});
			        
			        util.Control.setVisible(app, true,  ["btnDtlSave", "btnDtlClose"]);  //저장, 닫기
			        util.Control.setVisible(app, false, ["btnDtlRevise", "btnDtlDelete", "btnDtlCancel", "btnDtlList"]); //수정, 삭제, 취소
			        util.Control.setReadOnly(app, false, "grpData");
			        
			        util.DataSet.setValue(app, "dsList", 0, "MTG_NO", ""); //회의번호
			        util.DataSet.setValue(app, "dsList", 0, "MTG_HDMT_YMD", moment().format("YYYYMMDD"));
			        util.DataSet.setValue(app, "dsList", 0, "HDMT_BGNG_HR", moment().format("HHmm"));
			        
			    } else if(psType == "READ"){
			        util.Control.setVisible(app, true,  ["btnDtlRevise", "btnDtlDelete", "btnDtlClose"]);
			        util.Control.setVisible(app, false, ["btnDtlSave", "btnDtlCancel", "btnDtlList"]);
			        util.Control.setReadOnly(app, true, "grpData");

			    } else if(psType == "UPDATE") {
			        util.Control.setVisible(app, true,  ["btnDtlSave", "btnDtlClose"]);
			        util.Control.setVisible(app, false, ["btnDtlRevise", "btnDtlDelete", "btnDtlCancel", "btnDtlList"]);
			        util.Control.setReadOnly(app, false, "grpData");
			    }
			    
			}

