			function onBodyLoad(/* cpr.events.CEvent */ e){
			        
			    var voInitValue = app.getHostProperty("initValue");
			    var crudType = voInitValue["type"];
			    var rowData = voInitValue["data"];
			    
			    app.lookup("dsList").clearData();
			    app.lookup("dsAtndList").clearData();
			    
			    if (voInitValue["type"]){
			        setCrud(crudType);
			    }

			    util.Submit.send(app, 'subOnLoad', function(pbSuccess) {
			        if (pbSuccess) {
			            util.Msg.notify(app, "INF-M001");

			            if (crudType == "READ") {
			                util.DataMap.setValue(app, "dmListParam", "MTG_NO", rowData["MTG_NO"]);
			                doList();
			            } else {

			                doKey();  //key값가져오기 
			            }
			            
			            util.Control.redraw(app, "grpData");
			            
			            app.lookup("rdbCmitSe").focus();
			        }
			    });
			}

